mapper.select:
SELECT id
FROM meals
WHERE user_id = #{userId}
  AND meal_type = #{mealType}
  AND meal_date = #{mealDate}

mapper.delete:
DELETE FROM meals
WHERE id = #{mealId}
  AND user_id = #{userId}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM foods
    WHERE id = #{foodId}
)

SELECT id AS food_id, source_key, name AS food_name, brand, serving_description, serving_size, serving_unit, calories, carbohydrate, protein, fat FROM foods WHERE source_key IN
#{sourceKey}
ORDER BY source_key, serving_size NULLS LAST, serving_unit NULLS LAST, serving_description NULLS LAST, id
